function insertLine(source, name, line) {
  const start = `// zudojs:${name}:start`;
  const end = `// zudojs:${name}:end`;
  const s = source.indexOf(start);
  const e = source.indexOf(end);
  if (s === -1 || e === -1 || e < s) throw new Error("missing markers");
  const between = source.slice(s + start.length, e);
  if (between.split("\n").some((l) => l.trim() === line.trim())) return source;
  const lineStart = source.lastIndexOf("\n", e) + 1;
  const indent = source.slice(lineStart, e);
  return source.slice(0, lineStart) + indent + line.trim() + "\n" + source.slice(lineStart);
}

