function compareCapabilities(manifestList, featureList) {
  const inManifest = new Set(manifestList);
  const inFeatures = new Set(featureList);
  const lines = [
    ...manifestList.filter((c) => !inFeatures.has(c)).map((c) => `${c}: manifest only`),
    ...featureList.filter((c) => !inManifest.has(c)).map((c) => `${c}: package.json only`),
  ];
  return lines.length === 0 ? "same" : lines.join("; ");
}

