function parseArgs(argv) {
  const [command, ...rest] = argv;
  const args = [];
  const options = {};
  for (let i = 0; i < rest.length; i++) {
    const word = rest[i];
    if (word.startsWith("--")) {
      const value = rest[i + 1];
      options[word.slice(2)] = Number.isFinite(Number(value)) ? Number(value) : value;
      i++;
    } else {
      args.push(word);
    }
  }
  return { command, args, options };
}

